CustomField.formula:
Lower(
/*Prefix:*/
"OBD_"&

/*Dealer Name up to 35 chars, replacing spaces and periods:*/
SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(SUBSTITUTE(
IF(LEN(SUBSTITUTE( Account__r.Name , " ", "")) <= 35,
SUBSTITUTE(Account__r.Name , " ", ""),
LEFT(SUBSTITUTE(Account__r.Name , " ", ""), 35)
),
"'",""),
".",""),
",",""),
"/",""),
"&","")
&
"_" &
/*Date to make it unique*/
/*Year*/
Text(Year( DateValue(CreatedDate) ))&"_" &
/*Month*/
if(Month( DateValue(CreatedDate) )>10, Text(Month( DateValue(CreatedDate) )), "0"&Text(Month( DateValue(CreatedDate) )))&"_" &
/*Day*/
if(Day( DateValue(CreatedDate) )>10, Text(Day( DateValue(CreatedDate) )), "0"&Text(Day( DateValue(CreatedDate) ))) &"_" &
/*Time*/
Text(Hour( TIMEVALUE(CreatedDate)))&"_"&Text(Minute( TIMEVALUE(CreatedDate)))

)& Slack_Channel_Adjustment__c
